 * });
 * ```
 */
export function describeDatabase(
  name: string,
  fn: () => void,
  options?: {
    setup?: () => Promise<void>;
    teardown?: () => Promise<void>;
  },
): void {
  const testDatabaseUrl = process.env.TEST_DATABASE_URL ?? process.env.DATABASE_URL;
  const shouldSkip = !testDatabaseUrl || process.env.SKIP_DATABASE_TESTS === "true";

