// Use this to update a Nostr user's subscription status for testing
// Simply call this with:
// npx tsx ./tests/e2e/support/update-subscription-status.ts npub1xxx STATUS
//
// Where STATUS is one of: FREE, ACTIVE, EXPIRED, CANCELED, PAST_DUE

import { PrismaClient, SubscriptionStatus } from "@prisma/client";
import { installGlobals } from "@remix-run/node";
installGlobals();

const prisma = new PrismaClient();

type TestSubscriptionStatus = "FREE" | "ACTIVE" | "EXPIRED" | "CANCELED" | "PAST_DUE";

async function updateSubscriptionStatus(npub: string, targetStatus: TestSubscriptionStatus) {
    if (!npub) {
        throw new Error("npub required");
    }

    if (!targetStatus) {
        throw new Error("status required (FREE, ACTIVE, EXPIRED, CANCELED, PAST_DUE)");
    }

    // Find the user
    const user = await prisma.user.findUnique({
        where: { npub },
        include: { Subscription: true },
    });

    if (!user) {
        throw new Error(`User not found: ${npub}`);
    }

    if (targetStatus === "FREE") {
        // Delete any existing subscription to simulate free user
        if (user.Subscription) {
            await prisma.subscription.delete({
                where: { userId: user.id },
            });
        }

        console.log(`<status>FREE</status>`);
    } else if (targetStatus === "ACTIVE") {
        const now = new Date();
        const thirtyDaysFromNow = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update existing subscription to active
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.ACTIVE,
                    currentPeriodStart: now,
                    currentPeriodEnd: thirtyDaysFromNow,
                    cancelAtPeriodEnd: false,
                },
            });
        } else {
            // Create a new active subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.ACTIVE,
                    startDate: now,
                    currentPeriodStart: now,
                    currentPeriodEnd: thirtyDaysFromNow,
                },
            });
        }

        console.log(`<status>ACTIVE</status>`);
    } else if (targetStatus === "EXPIRED") {
        const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
        const sixtyDaysAgo = new Date(Date.now() - 60 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update subscription to expired (INACTIVE status with past end date)
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.INACTIVE,
                    currentPeriodStart: sixtyDaysAgo,
                    currentPeriodEnd: thirtyDaysAgo,
                    endDate: thirtyDaysAgo,
                },
            });
        } else {
            // Create an expired subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.INACTIVE,
                    startDate: sixtyDaysAgo,
                    currentPeriodStart: sixtyDaysAgo,
                    currentPeriodEnd: thirtyDaysAgo,
                    endDate: thirtyDaysAgo,
                },
            });
        }

        console.log(`<status>EXPIRED</status>`);
    } else if (targetStatus === "CANCELED") {
        const now = new Date();
        const thirtyDaysFromNow = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update subscription to canceled (still active until period end, but won't renew)
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.CANCELED,
                    currentPeriodEnd: thirtyDaysFromNow,
                    cancelAtPeriodEnd: true,
                },
            });
        } else {
            // Create a canceled subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.CANCELED,
                    startDate: now,
                    currentPeriodStart: now,
                    currentPeriodEnd: thirtyDaysFromNow,
                    cancelAtPeriodEnd: true,
                },
            });
        }

        console.log(`<status>CANCELED</status>`);
    } else if (targetStatus === "PAST_DUE") {
        const now = new Date();
        const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

        if (user.Subscription) {
            // Update subscription to past due
            await prisma.subscription.update({
                where: { userId: user.id },
                data: {
                    status: SubscriptionStatus.PAST_DUE,
                    currentPeriodEnd: sevenDaysAgo,
                },
            });
        } else {
            // Create a past due subscription
            let plan = await prisma.plan.findFirst({
                where: { id: "premium" },
            });

            if (!plan) {
                plan = await prisma.plan.findFirst({
                    where: { isActive: true },
                });
            }

            if (!plan) {
                throw new Error("No plan found in database");
            }

            const subscriptionId = `test_sub_${Date.now()}_${user.id.slice(-8)}`;
            await prisma.subscription.create({
                data: {
                    id: subscriptionId,
                    userId: user.id,
                    planId: plan.id,
                    status: SubscriptionStatus.PAST_DUE,
                    startDate: sevenDaysAgo,
                    currentPeriodStart: sevenDaysAgo,
                    currentPeriodEnd: sevenDaysAgo,
                },
            });
        }

        console.log(`<status>PAST_DUE</status>`);
    } else {
        throw new Error(`Unknown status: ${targetStatus}`);
    }

    await prisma.$disconnect();
}

updateSubscriptionStatus(process.argv[2], process.argv[3] as TestSubscriptionStatus);

/**
 * Payment factory for creating test payments
 * Uses builder pattern for flexible test data creation
 */

import { Decimal } from "@prisma/client/runtime/library";

import type { Payment, PaymentStatus } from "@prisma/client";

import { TEST_USER_ID } from "../utils/test-helpers";

export interface PaymentFactoryOptions {
  id?: string;
  userId?: string;
  amount?: number;
  amountUsd?: number | null;
  invoice?: string;
  paymentHash?: string;
  preimage?: string | null;
  status?: PaymentStatus;
  description?: string | null;
  subscriptionId?: string | null;
  expiresAt?: Date | null;
  paidAt?: Date | null;
  failedAt?: Date | null;
  failureReason?: string | null;
  paymentMethod?: string | null;
  createdAt?: Date;
  updatedAt?: Date;
}

export class PaymentFactory {
  private options: PaymentFactoryOptions;

  constructor(options: PaymentFactoryOptions = {}) {
    const paymentId = `payment-${Date.now()}-${Math.random().toString(36).substring(7)}`;
    this.options = {
      id: paymentId,
      userId: TEST_USER_ID,
      amount: 1000, // 1000 sats
      amountUsd: null,
      invoice: `lnbc${Math.random().toString(36).substring(7)}`,
      paymentHash: `hash-${Math.random().toString(36).substring(7)}`,
      preimage: null,
      status: "PENDING",
      description: null,
      subscriptionId: null,
      expiresAt: new Date(Date.now() + 3600000), // 1 hour from now
      paidAt: null,
      failedAt: null,
      failureReason: null,
      paymentMethod: null,
      createdAt: new Date(),
      updatedAt: new Date(),
      ...options,
    };
  }

  withId(id: string): this {
    this.options.id = id;
    return this;
  }

  withUserId(userId: string): this {
    this.options.userId = userId;
    return this;
  }

  withAmount(amount: number, amountUsd?: number): this {
    this.options.amount = amount;
    this.options.amountUsd = amountUsd ?? null;
    return this;
  }

  withInvoice(invoice: string): this {
    this.options.invoice = invoice;
    return this;
  }

  withPaymentHash(paymentHash: string): this {
    this.options.paymentHash = paymentHash;
    return this;
  }

  asPending(): this {
    this.options.status = "PENDING";
    this.options.paidAt = null;
    this.options.failedAt = null;
    return this;
  }

  asPaid(paidAt?: Date): this {
    this.options.status = "COMPLETED";
    this.options.paidAt = paidAt ?? new Date();
    this.options.failedAt = null;
    this.options.preimage = `preimage-${Math.random().toString(36).substring(7)}`;
    return this;
  }

  asFailed(failureReason?: string, failedAt?: Date): this {
    this.options.status = "FAILED";
    this.options.failedAt = failedAt ?? new Date();
    this.options.failureReason = failureReason ?? "Payment failed";
    this.options.paidAt = null;
    return this;
  }

  withSubscription(subscriptionId: string): this {
    this.options.subscriptionId = subscriptionId;
    return this;
  }

  withDescription(description: string): this {
    this.options.description = description;
    return this;
  }

  withExpiresAt(expiresAt: Date): this {
    this.options.expiresAt = expiresAt;
    return this;
  }

  build(): Payment {
    // eslint-disable-next-line @typescript-eslint/consistent-type-assertions
    return {
      id: this.options.id!,
      userId: this.options.userId!,
      amount: this.options.amount ?? 0,
      amountUsd: this.options.amountUsd !== null && this.options.amountUsd !== undefined
        ? new Decimal(this.options.amountUsd)
        : null,
      invoice: this.options.invoice ?? "",
      paymentHash: this.options.paymentHash ?? "",
      preimage: this.options.preimage ?? null,
      status: this.options.status ?? "PENDING",
      description: this.options.description ?? null,
      subscriptionId: this.options.subscriptionId ?? null,
      expiresAt: this.options.expiresAt ?? null,
      paidAt: this.options.paidAt ?? null,
      failedAt: this.options.failedAt ?? null,
      failureReason: this.options.failureReason ?? null,
      paymentMethod: this.options.paymentMethod ?? null,
      createdAt: this.options.createdAt ?? new Date(),
      updatedAt: this.options.updatedAt ?? new Date(),
    } as Payment;
  }
}

/**
 * Convenience functions for common payment types
 */
export const paymentFactory = {
  /**
   * Create a pending payment
   */
  pending: (overrides?: PaymentFactoryOptions) => {
    return new PaymentFactory(overrides).asPending().build();
  },

  /**
   * Create a completed payment
   */
  paid: (overrides?: PaymentFactoryOptions) => {
    return new PaymentFactory(overrides).asPaid().build();
  },

  /**
   * Create a failed payment
   */
  failed: (failureReason?: string, overrides?: PaymentFactoryOptions) => {
    return new PaymentFactory(overrides).asFailed(failureReason).build();
  },

  /**
   * Create multiple payments
   */
  many: (count: number, overrides?: PaymentFactoryOptions) => {
    return Array.from({ length: count }, (_, i) =>
      new PaymentFactory({ ...overrides, id: `payment-${i + 1}` }).build(),
    );
  },
};

