      // Constructor implementation
    }
  }
  return {
    default: RedisMock,
  };
});

// Import after mocks are set up
import { queueClient, getQueueInstance } from "~/infra/queue/queue-client.server";

describe("Queue Client", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    process.env.REDIS_URL = "redis://localhost:6379";
    // Clear the queues map by getting a fresh instance
    // This ensures each test starts with a clean state
  });

  describe("Enqueue Operations", () => {
    it("should enqueue job with delay option", async () => {
      const mockJob = {
        id: "job-123",
      } satisfies Partial<Job> as Job;

      mockQueue.add.mockResolvedValue(mockJob);

      const result = await queueClient.enqueue(
        "scheduled-posts",
        "publish-post",
        { postId: "post-123", userId: "user-123", signedEvent: { id: "event-123", pubkey: "test-pubkey", created_at: Date.now(), kind: 1, tags: [], content: "", sig: "test-sig" } satisfies Partial<SignedEvent> as SignedEvent },
        { delay: 5000 },
      );

      expect(mockQueue.add).toHaveBeenCalledWith(
        "publish-post",
        { postId: "post-123", userId: "user-123", signedEvent: { id: "event-123", pubkey: "test-pubkey", created_at: Date.now(), kind: 1, tags: [], content: "", sig: "test-sig" } satisfies Partial<SignedEvent> as SignedEvent },
        { delay: 5000 },
      );
      expect(result).toEqual({
        success: true,
        jobId: "job-123",
      });
    });

    it("should enqueue job with scheduledFor option", async () => {
      const mockJob = {
        id: "job-123",
      } satisfies Partial<Job> as Job;

      const scheduledFor = Math.floor(Date.now() / 1000) + 3600; // 1 hour from now
      mockQueue.add.mockResolvedValue(mockJob);

      const result = await queueClient.enqueue(
        "scheduled-posts",
        "publish-post",
        { postId: "post-123", userId: "user-123", signedEvent: { id: "event-123", pubkey: "test-pubkey", created_at: Date.now(), kind: 1, tags: [], content: "", sig: "test-sig" } satisfies Partial<SignedEvent> as SignedEvent },
        { scheduledFor },
      );

      expect(mockQueue.add).toHaveBeenCalled();
      expect(result.success).toBe(true);
      expect(result.jobId).toBe("job-123");
    });

    it("should return error for past scheduledFor timestamp", async () => {
      const pastTime = Math.floor(Date.now() / 1000) - 3600; // 1 hour ago

      const result = await queueClient.enqueue(
        "scheduled-posts",
        "publish-post",
        { postId: "post-123", userId: "user-123", signedEvent: { id: "event-123", pubkey: "test-pubkey", created_at: Date.now(), kind: 1, tags: [], content: "", sig: "test-sig" } satisfies Partial<SignedEvent> as SignedEvent },
        { scheduledFor: pastTime },
      );

      expect(result.success).toBe(false);
      expect(result.error).toBe("Scheduled time must be in the future");
    });

    it("should handle enqueue errors", async () => {
      mockQueue.add.mockRejectedValue(new Error("Queue error"));

      const result = await queueClient.enqueue(
        "scheduled-posts",
        "publish-post",
        { postId: "post-123", userId: "user-123", signedEvent: { id: "event-123", pubkey: "test-pubkey", created_at: Date.now(), kind: 1, tags: [], content: "", sig: "test-sig" } satisfies Partial<SignedEvent> as SignedEvent },
      );

      expect(result.success).toBe(false);
      expect(result.error).toBe("Queue error");
    });
  });

  describe("Cancel Operations", () => {
    it("should cancel job by data key", async () => {
      const mockJob = {
        id: "job-123",
        data: { postId: "post-123" },
        remove: vi.fn().mockResolvedValue(undefined),
      } as unknown as Job;

      mockQueue.getJobs.mockResolvedValue([mockJob]);

      const result = await queueClient.cancelByData(
        "scheduled-posts",
        "postId",
